import sys

def solver(n, m):
    first = 0
    second = 0
    copyN = n
    point = m if m % 2 == 0 else m + 1

    while copyN != point / 2:
        if copyN > point / 2:
            first += copyN - (point / 2)
            copyN = point / 2
        if copyN < point / 2:
            copyN *= 2
            first += 1
    first += 1 if m % 2 == 0 else 2

    copyN = n
    while copyN != m:
        if copyN < m:
            copyN *= 2
        else:
            second += copyN - m
            break
        second += 1

    return min(first, second)


def main():
    input_data = sys.stdin.read().split('\n')
    n, m = map(int, input_data[0].split(' '))

    if n > m:
        print(n - m)
        return

    data = {n: n}
    find = 0

    while True:
        map_ = {}
        for i in list(data.keys()):
            x = int(i)
            if x - 1 >= 1:
                map_[x - 1] = x - 1
                if x - 1 == m:
                    print(find + 1)
                    return
            if x * 2 <= m * 1.5:
                map_[x * 2] = x * 2
                if x * 2 == m:
                    print(find + 1)
                    return
        data = map_
        find += 1


if __name__ == "__main__":
    main()

